data.minimal_example:
SSEClient.subscribeToSSE(
    method: SSERequestType.GET,
    url: 'http://192.168.1.2:3000/api/activity-stream',
    header: {
        "Accept": "text/event-stream",
    }).listen((event) {
        print('Id: ' + event.id!);
        print('Event: ' + event.event!);
        print('Data: ' + event.data!);
    },
);
